    return intro('Help & support','Let’s get it sorted.','Find an answer or get in touch about an existing service.')+f'<section class="section"><div class="wrap"><div class="cards">{cards}</div></div></section><section class="section section-tint"><div class="wrap split"><div><h2>Common questions.</h2><p class="lead">A few things to know before getting started.</p>{btn("Contact us","contact.html?service=support")}</div>{faq()}</div></section>'
