    extensions=''.join(f'<option value="{d["extension"]}">.{d["extension"]} · R{money(d["price"])} / year</option>' for d in CONFIG['domainExamples'])
    return intro('Hosting & domains','Choose the right setup.','Select your hosting package, billing cycle and domain. See an estimated first-term price before you enquire.')+f'''<section class="section checkout-section"><div class="wrap checkout-grid"><div><div class="checkout-steps" aria-label="Setup steps"><span class="active">01 Choose</span><span>02 Request setup</span></div><form class="checkout-form card" data-checkout><h2>Your setup</h2><label for="checkout-plan">Hosting package</label><select name="plan" id="checkout-plan">{options}</select><label for="checkout-cycle">Billing cycle</label><select name="cycle" id="checkout-cycle"><option value="monthly">Monthly</option><option value="yearly">Yearly · full annual payment</option></select><label for="checkout-domain-choice">Your domain</label><select name="domain-choice" id="checkout-domain-choice"><option value="later">I’ll choose my domain later</option><option value="existing">I already have a domain</option><option value="register">I’d like a new domain</option></select><div data-checkout-domain-fields hidden><label for="checkout-domain">Domain name</label><input name="domain" id="checkout-domain" placeholder="yourbusiness.co.za" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="253" aria-describedby="checkout-domain-note"><p id="checkout-domain-note" class="input-help">Availability and renewal price are confirmed before registration.</p><div data-checkout-extension-field hidden><label for="checkout-extension">Domain ending</label><select name="extension" id="checkout-extension">{extensions}</select></div></div><button class="btn btn-primary" type="submit" disabled>Review my setup <span aria-hidden="true">→</span></button><p class="field-error checkout-error" role="alert" hidden></p></form><section class="order-review card" data-order-review hidden tabindex="-1"><p class="eyebrow">Your selections</p><h2>Ready for the next step?</h2><p>Mumatec will confirm domain availability, the current total and renewal terms before any service is set up.</p><a class="btn btn-primary" data-request-link>Ask Mumatec about this setup <span aria-hidden="true">↗</span></a><p class="input-help">Your email app opens with the details ready to review.</p></section></div><aside class="order-summary card" aria-labelledby="summary-heading"><p class="eyebrow">Your selections</p><h2 id="summary-heading">Setup summary</h2><div class="summary-package"><span data-summary-package>Start-Up 15</span><strong data-summary-storage>15 GB NVMe SSD</strong><span data-summary-cycle>Monthly billing</span></div><dl class="summary-lines"><div><dt>Hosting</dt><dd data-summary-hosting>R59 / month</dd></div><div><dt>Domain registration</dt><dd data-summary-domain>Not added</dd></div></dl><div class="summary-total"><span>Estimated first term</span><strong data-summary-total aria-live="polite" aria-atomic="true">R59</strong></div><p class="input-help" data-summary-renewal>Hosting renews monthly. Domain registration is separate.</p><div class="service-note"><strong>Price guide.</strong> Mumatec confirms availability, applicable taxes and current renewal terms before an order is placed.</div><a href="hosting.html#hosting-plans">Compare hosting packages ↗</a></aside></div></section>'''

